1: import * as r from 'restructure';
2: import { cache } from './decorators';
3: import * as fontkit from './base';
4: import Directory from './tables/directory';
5: import tables from './tables';
6: import CmapProcessor from './CmapProcessor';
7: import LayoutEngine from './layout/LayoutEngine';
8: import TTFGlyph from './glyph/TTFGlyph';
9: import CFFGlyph from './glyph/CFFGlyph';
10: import SBIXGlyph from './glyph/SBIXGlyph';
11: import COLRGlyph from './glyph/COLRGlyph';
12: import GlyphVariationProcessor from './glyph/GlyphVariationProcessor';
13: import TTFSubset from './subset/TTFSubset';
14: import CFFSubset from './subset/CFFSubset';
15: import BBox from './glyph/BBox';
16: import { asciiDecoder } from './utils';
17: 
18: /**
19:  * This is the base class for all SFNT-based font formats in fontkit.
20:  * It supports TrueType, and PostScript glyphs, and several color glyph formats.
21:  */
22: export default class TTFFont {
23:   type = 'TTF';
24: 
25:   static probe(buffer) {
26:     let format = asciiDecoder.decode(buffer.slice(0, 4));
27:     return format === 'true' || format === 'OTTO' || format === String.fromCharCode(0, 1, 0, 0);
28:   }
29: 
30:   constructor(stream, variationCoords = null) {
31:     this.defaultLanguage = null;
32:     this.stream = stream;
33:     this.variationCoords = variationCoords;
34: 
35:     this._directoryPos = this.stream.pos;
36:     this._tables = {};
37:     this._glyphs = {};
38:     this._decodeDirectory();
39: 
40:     // define properties for each table to lazily parse
41:     for (let tag in this.directory.tables) {
42:       let table = this.directory.tables[tag];
43:       if (tables[tag] && table.length > 0) {
44:         Object.defineProperty(this, tag, {
45:           get: this._getTable.bind(this, table)
46:         });
47:       }
48:     }
49:   }
50: 
51:   setDefaultLanguage(lang = null) {
52:     this.defaultLanguage = lang;
53:   }
54: 
55:   _getTable(table) {
56:     if (!(table.tag in this._tables)) {
57:       try {
58:         this._tables[table.tag] = this._decodeTable(table);
59:       } catch (e) {
60:         if (fontkit.logErrors) {
61:           console.error(`Error decoding table ${table.tag}`);
62:           console.error(e.stack);
63:         }
64:       }
65:     }
66: 
67:     return this._tables[table.tag];
68:   }
69: 
70:   _getTableStream(tag) {
71:     let table = this.directory.tables[tag];
72:     if (table) {
73:       this.stream.pos = table.offset;
74:       return this.stream;
75:     }
76: 
77:     return null;
78:   }
79: 
80:   _decodeDirectory() {
81:     return this.directory = Directory.decode(this.stream, {_startOffset: 0});
82:   }
83: 
84:   _decodeTable(table) {
85:     let pos = this.stream.pos;
86: 
87:     let stream = this._getTableStream(table.tag);
88:     let result = tables[table.tag].decode(stream, this, table.length);
89: 
90:     this.stream.pos = pos;
91:     return result;
92:   }
93: 
94:   /**
95:    * Gets a string from the font's `name` table
96:    * `lang` is a BCP-47 language code.
97:    * @return {string}
98:    */
99:   getName(key, lang = this.defaultLanguage || fontkit.defaultLanguage) {
100:     let record = this.name && this.name.records[key];
101:     if (record) {
102:       // Attempt to retrieve the entry, depending on which translation is available:
103:       return (
104:           record[lang]
105:           || record[this.defaultLanguage]
106:           || record[fontkit.defaultLanguage]
107:           || record['en']
108:           || record[Object.keys(record)[0]] // Seriously, ANY language would be fine
109:           || null
110:       );
111:     }
112: 
113:     return null;
114:   }
115: 
116:   /**
117:    * The unique PostScript name for this font, e.g. "Helvetica-Bold"
118:    * @type {string}
119:    */
120:   get postscriptName() {
121:     return this.getName('postscriptName');
122:   }
123: 
124:   /**
125:    * The font's full name, e.g. "Helvetica Bold"
126:    * @type {string}
127:    */
128:   get fullName() {
129:     return this.getName('fullName');
130:   }
131: 
132:   /**
133:    * The font's family name, e.g. "Helvetica"
134:    * @type {string}
135:    */
136:   get familyName() {
137:     return this.getName('fontFamily');
138:   }
139: 
140:   /**
141:    * The font's sub-family, e.g. "Bold".
142:    * @type {string}
143:    */
144:   get subfamilyName() {
145:     return this.getName('fontSubfamily');
146:   }
147: 
148:   /**
149:    * The font's copyright information
150:    * @type {string}
151:    */
152:   get copyright() {
153:     return this.getName('copyright');
154:   }
155: 
156:   /**
157:    * The font's version number
158:    * @type {string}
159:    */
160:   get version() {
161:     return this.getName('version');
162:   }
163: 
164:   /**
165:    * The font’s [ascender](https://en.wikipedia.org/wiki/Ascender_(typography))
166:    * @type {number}
167:    */
168:   get ascent() {
169:     return this.hhea.ascent;
170:   }
171: 
172:   /**
173:    * The font’s [descender](https://en.wikipedia.org/wiki/Descender)
174:    * @type {number}
175:    */
176:   get descent() {
177:     return this.hhea.descent;
178:   }
179: 
180:   /**
181:    * The amount of space that should be included between lines
182:    * @type {number}
183:    */
184:   get lineGap() {
185:     return this.hhea.lineGap;
186:   }
187: 
188:   /**
189:    * The offset from the normal underline position that should be used
190:    * @type {number}
191:    */
192:   get underlinePosition() {
193:     return this.post.underlinePosition;
194:   }
195: 
196:   /**
197:    * The weight of the underline that should be used
198:    * @type {number}
199:    */
200:   get underlineThickness() {
201:     return this.post.underlineThickness;
202:   }
203: 
204:   /**
205:    * If this is an italic font, the angle the cursor should be drawn at to match the font design
206:    * @type {number}
207:    */
208:   get italicAngle() {
209:     return this.post.italicAngle;
210:   }
211: 
212:   /**
213:    * The height of capital letters above the baseline.
214:    * See [here](https://en.wikipedia.org/wiki/Cap_height) for more details.
215:    * @type {number}
216:    */
217:   get capHeight() {
218:     let os2 = this['OS/2'];
219:     return os2 ? os2.capHeight : this.ascent;
220:   }
221: 
222:   /**
223:    * The height of lower case letters in the font.
224:    * See [here](https://en.wikipedia.org/wiki/X-height) for more details.
225:    * @type {number}
226:    */
227:   get xHeight() {
228:     let os2 = this['OS/2'];
229:     return os2 ? os2.xHeight : 0;
230:   }
231: 
232:   /**
233:    * The number of glyphs in the font.
234:    * @type {number}
235:    */
236:   get numGlyphs() {
237:     return this.maxp.numGlyphs;
238:   }
239: 
240:   /**
241:    * The size of the font’s internal coordinate grid
242:    * @type {number}
243:    */
244:   get unitsPerEm() {
245:     return this.head.unitsPerEm;
246:   }
247: 
248:   /**
249:    * The font’s bounding box, i.e. the box that encloses all glyphs in the font.
250:    * @type {BBox}
251:    */
252:   @cache
253:   get bbox() {
254:     return Object.freeze(new BBox(this.head.xMin, this.head.yMin, this.head.xMax, this.head.yMax));
255:   }
256: 
257:   @cache
258:   get _cmapProcessor() {
259:     return new CmapProcessor(this.cmap);
260:   }
261: 
262:   /**
263:    * An array of all of the unicode code points supported by the font.
264:    * @type {number[]}
265:    */
266:   @cache
267:   get characterSet() {
268:     return this._cmapProcessor.getCharacterSet();
269:   }
270: 
271:   /**
272:    * Returns whether there is glyph in the font for the given unicode code point.
273:    *
274:    * @param {number} codePoint
275:    * @return {boolean}
276:    */
277:   hasGlyphForCodePoint(codePoint) {
278:     return !!this._cmapProcessor.lookup(codePoint);
279:   }
280: 
281:   /**
282:    * Maps a single unicode code point to a Glyph object.
283:    * Does not perform any advanced substitutions (there is no context to do so).
284:    *
285:    * @param {number} codePoint
286:    * @return {Glyph}
287:    */
288:   glyphForCodePoint(codePoint) {
289:     return this.getGlyph(this._cmapProcessor.lookup(codePoint), [codePoint]);
290:   }
291: 
292:   /**
293:    * Returns an array of Glyph objects for the given string.
294:    * This is only a one-to-one mapping from characters to glyphs.
295:    * For most uses, you should use font.layout (described below), which
296:    * provides a much more advanced mapping supporting AAT and OpenType shaping.
297:    *
298:    * @param {string} string
299:    * @return {Glyph[]}
300:    */
301:   glyphsForString(string) {
302:     let glyphs = [];
303:     let len = string.length;
304:     let idx = 0;
305:     let last = -1;
306:     let state = -1;
307: 
308:     while (idx <= len) {
309:       let code = 0;
310:       let nextState = 0;
311: 
312:       if (idx < len) {
313:         // Decode the next codepoint from UTF 16
314:         code = string.charCodeAt(idx++);
315:         if (0xd800 <= code && code <= 0xdbff && idx < len) {
316:           let next = string.charCodeAt(idx);
317:           if (0xdc00 <= next && next <= 0xdfff) {
318:             idx++;
319:             code = ((code & 0x3ff) << 10) + (next & 0x3ff) + 0x10000;
320:           }
321:         }
322: 
323:         // Compute the next state: 1 if the next codepoint is a variation selector, 0 otherwise.
324:         nextState = ((0xfe00 <= code && code <= 0xfe0f) || (0xe0100 <= code && code <= 0xe01ef)) ? 1 : 0;
325:       } else {
326:         idx++;
327:       }
328: 
329:       if (state === 0 && nextState === 1) {
330:         // Variation selector following normal codepoint.
331:         glyphs.push(this.getGlyph(this._cmapProcessor.lookup(last, code), [last, code]));
332:       } else if (state === 0 && nextState === 0) {
333:         // Normal codepoint following normal codepoint.
334:         glyphs.push(this.glyphForCodePoint(last));
335:       }
336: 
337:       last = code;
338:       state = nextState;
339:     }
340: 
341:     return glyphs;
342:   }
343: 
344:   @cache
345:   get _layoutEngine() {
346:     return new LayoutEngine(this);
347:   }
348: 
349:   /**
350:    * Returns a GlyphRun object, which includes an array of Glyphs and GlyphPositions for the given string.
351:    *
352:    * @param {string} string
353:    * @param {string[]} [userFeatures]
354:    * @param {string} [script]
355:    * @param {string} [language]
356:    * @param {string} [direction]
357:    * @return {GlyphRun}
358:    */
359:   layout(string, userFeatures, script, language, direction) {
360:     return this._layoutEngine.layout(string, userFeatures, script, language, direction);
361:   }
362: 
363:   /**
364:    * Returns an array of strings that map to the given glyph id.
365:    * @param {number} gid - glyph id
366:    */
367:   stringsForGlyph(gid) {
368:     return this._layoutEngine.stringsForGlyph(gid);
369:   }
370: 
371:   /**
372:    * An array of all [OpenType feature tags](https://www.microsoft.com/typography/otspec/featuretags.htm)
373:    * (or mapped AAT tags) supported by the font.
374:    * The features parameter is an array of OpenType feature tags to be applied in addition to the default set.
375:    * If this is an AAT font, the OpenType feature tags are mapped to AAT features.
376:    *
377:    * @type {string[]}
378:    */
379:   get availableFeatures() {
380:     return this._layoutEngine.getAvailableFeatures();
381:   }
382: 
383:   getAvailableFeatures(script, language) {
384:     return this._layoutEngine.getAvailableFeatures(script, language);
385:   }
386: 
387:   _getBaseGlyph(glyph, characters = []) {
388:     if (!this._glyphs[glyph]) {
389:       if (this.directory.tables.glyf) {
390:         this._glyphs[glyph] = new TTFGlyph(glyph, characters, this);
391: 
392:       } else if (this.directory.tables['CFF '] || this.directory.tables.CFF2) {
393:         this._glyphs[glyph] = new CFFGlyph(glyph, characters, this);
394:       }
395:     }
396: 
397:     return this._glyphs[glyph] || null;
398:   }
399: 
400:   /**
401:    * Returns a glyph object for the given glyph id.
402:    * You can pass the array of code points this glyph represents for
403:    * your use later, and it will be stored in the glyph object.
404:    *
405:    * @param {number} glyph
406:    * @param {number[]} characters
407:    * @return {Glyph}
408:    */
409:   getGlyph(glyph, characters = []) {
410:     if (!this._glyphs[glyph]) {
411:       if (this.directory.tables.sbix) {
412:         this._glyphs[glyph] = new SBIXGlyph(glyph, characters, this);
413: 
414:       } else if ((this.directory.tables.COLR) && (this.directory.tables.CPAL)) {
415:         this._glyphs[glyph] = new COLRGlyph(glyph, characters, this);
416: 
417:       } else {
418:         this._getBaseGlyph(glyph, characters);
419:       }
420:     }
421: 
422:     return this._glyphs[glyph] || null;
423:   }
424: 
425:   /**
426:    * Returns a Subset for this font.
427:    * @return {Subset}
428:    */
429:   createSubset() {
430:     if (this.directory.tables['CFF ']) {
431:       return new CFFSubset(this);
432:     }
433: 
434:     return new TTFSubset(this);
435:   }
436: 
437:   /**
438:    * Returns an object describing the available variation axes
439:    * that this font supports. Keys are setting tags, and values
440:    * contain the axis name, range, and default value.
441:    *
442:    * @type {object}
443:    */
444:   @cache
445:   get variationAxes() {
446:     let res = {};
447:     if (!this.fvar) {
448:       return res;
449:     }
450: 
451:     for (let axis of this.fvar.axis) {
452:       res[axis.axisTag.trim()] = {
453:         name: axis.name.en,
454:         min: axis.minValue,
455:         default: axis.defaultValue,
